INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('Bourgmestres et échevins (Luxembourg)', 'Collèges des bourgmestre et échevins depuis les élections communales 2023', 'lu_pep_municipal', 'PEP', 'https://data.public.lu/fr/datasets/college-des-bourgmestre-et-echevins-depuis-les-elections-communales-2023/', 'lu-pep-municipal', 'D:\\test parser 2\\plugins\\swiftcheck-aml-lu-pep-municipal-0.0.1-SNAPSHOT.jar', 'HTTP_FILE', 'OPEN_DATA_FILE', 'https://data.public.lu/fr/datasets/r/067d11cc-29a8-4f0c-bf35-f9d4ac1818ec', '{"yearsAfterEnd": "5"}', 24, 12, NULL, 'Ministère des Affaires intérieures, data.public.lu', NULL, TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former) SELECT f.id, p.id, 'COMPLETE', FALSE FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'LU-AMLR' AND f.label = 'Bourgmestre ou échevin de la Ville de Luxembourg' AND p.dataset_name = 'lu_pep_municipal';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former) SELECT f.id, p.id, 'COMPLETE', FALSE FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'LU-MUN' AND f.label = 'Bourgmestre' AND p.dataset_name = 'lu_pep_municipal';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former) SELECT f.id, p.id, 'COMPLETE', FALSE FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'LU-MUN' AND f.label = 'Échevin' AND p.dataset_name = 'lu_pep_municipal';

